import { spawnSync } from 'node:child_process';
import { writeFileSync } from 'node:fs';
const REF = '/workspace/dataset/test2_executable';
// deterministic LCG so the corpus is reproducible
let s = 123456789;
const rnd = () => (s = (s * 1103515245 + 12345) % 2147483648) / 2147483648;
const pick = (a) => a[Math.floor(rnd() * a.length)];
const POOLS = [
  Array.from({length:95},(_,i)=>String.fromCharCode(32+i)),          // ascii printable
  [...'密码パスソルト盐한국어АБВΑΒΓאבגالعربية'],                       // multi-script
  [...'😀🔑🧂👨‍👩‍👧‍👦🏳️‍🌈🇯🇵é́ñ̃'],                                        // emoji/combining
  [...'-_=+.$@#%^&*(){}[]|\\/<>?!~`\'" \t'],                          // punctuation heavy
];
const mkstr = (n) => { const p = pick(POOLS); let o=''; for(let i=0;i<n;i++) o += pick(p); return o; };
const cases = [];
// canonical vectors
for (const c of [
  ["p'_xyB9J", '$2b$12$aTIircdJsS8iO3WFg3aKsE', 500],
  ['=BH[kuEw', 'salt_740344', 10000],
  ['RxgG9oiZ', 'FeKORdjj', 5000],
  [',XD0fO8{', '$2b$12$v3g32CgH6DaUjA3PjeEYqv', 1000],
  ['password','salt',1],['password','salt',2],['password','salt',4096],
  ['','',1],['','',1000],
]) cases.push(c);
// boundary-length sweep: salt lengths crossing SHA-1 padding (salt+4 bytes)
for (let n = 0; n <= 80; n++) cases.push(['k'.repeat(n % 70), 'x'.repeat(n), 7]);
// key-length sweep across HMAC block size
for (let n = 0; n <= 130; n++) cases.push(['A'.repeat(n), 'salt', 3]);
// randomised
for (let i = 0; i < 320; i++) {
  cases.push([mkstr(Math.floor(rnd()*40)), mkstr(Math.floor(rnd()*40)), 1 + Math.floor(rnd()*2500)]);
}
const out = [];
for (const [a,b,c] of cases) {
  const r = spawnSync(REF, ['--a',a,'--b',b,'--c',String(c)], {encoding:'buffer'});
  out.push({a,b,c,status:r.status,stdout:r.stdout.toString('utf8'),stderr:r.stderr.toString('utf8')});
}
writeFileSync('/tmp/golden.json', JSON.stringify(out));
console.log('golden cases:', out.length, 'nonzero rc:', out.filter(o=>o.status!==0).length);
EOF
