cat > /tmp/check_golden.mjs <<'EOF'
import { spawnSync } from 'node:child_process';
import { readFileSync } from 'node:fs';
const g = JSON.parse(readFileSync('/tmp/golden.json','utf8'));
const norm = (s) => s.replace(/PYI-\d+/g,'PYI-N').replace(/test2_executable|test2\.mjs/g,'PROG');
let fail = 0, n = 0;
for (const o of g) {
  const r = spawnSync('node', ['/output/test2.mjs','--a',o.a,'--b',o.b,'--c',String(o.c)], {encoding:'buffer'});
  const so = r.stdout.toString('utf8'), se = r.stderr.toString('utf8');
  n++;
  if (so !== o.stdout || norm(se) !== norm(o.stderr) || r.status !== o.status) {
    if (fail < 12) console.log('MISMATCH', JSON.stringify({a:o.a,b:o.b,c:o.c}),
      '\n  exp rc=%d out=%j err=%j', o.status, o.stdout, norm(o.stderr),
      '\n  got rc=%d out=%j err=%j', r.status, so, norm(se));
    fail++;
  }
}
console.log(`\ngolden: ${n-fail}/${n} passed, ${fail} failed`);
process.exit(fail ? 1 : 0);
EOF
