1	/**
2	 * Python-style exception objects plus CPython/PyInstaller traceback rendering.
3	 *
4	 * The reference program is a PyInstaller one-file bundle, so an unhandled
5	 * exception writes a normal CPython traceback to stderr and then PyInstaller's
6	 * own `[PYI-<pid>:ERROR] ...` line. Both are reproduced byte-for-byte here.
7	 */
8	
9	import process from 'node:process';
10	
11	/** Number of spaces CPython puts in front of a source line inside a traceback. */
12	const SOURCE_INDENT = 4;
13	
14	/**
15	 * Frame 1 of every traceback this program can produce: the single statement of
16	 * test2.py that constructs the PBKDF2 object. CPython underlines the
17	 * sub-expression that actually raised, which here is always the
18	 * `pbkdf2.PBKDF2(...)` call (the trailing `.read(20)` is never reached).
19	 */
20	const MAIN_SOURCE =
21	  'result = pbkdf2.PBKDF2(args.a, args.b, iterations=args.c).read(20)  # 派生 20 字节密钥';
22	const MAIN_CARET_EXPR = 'pbkdf2.PBKDF2(args.a, args.b, iterations=args.c)';
23	
24	/** `pbkdf2.py` line reported for `_setup` when the error carries no `frameLine`. */
25	const DEFAULT_SETUP_LINE = 205;
26	
27	/** Base class for every exception we mirror from Python. */
28	export class PyError extends Error {
29	  /**
30	   * @param {string} type Python exception class name, e.g. `'ValueError'`.
31	   * @param {string} message Python's `str(exc)` text.
32	   */
33	  constructor(type, message) {
34	    super(message);
35	    this.name = type;
36	    this.pyType = type;
37	    this.pyMessage = message;
38	    /**
39	     * Line inside `pbkdf2.py`'s `_setup` that raised. The raising module tags
40	     * this (193 passphrase, 197 salt, 205 iterations) so the traceback's last
41	     * frame matches the real interpreter.
42	     * @type {number|undefined}
43	     */
44	    this.frameLine = undefined;
45	  }
46	}
47	
48	/** Python `ValueError`. */
49	export class PyValueError extends PyError {
50	  /** @param {string} message */
51	  constructor(message) {
52	    super('ValueError', message);
53	  }
54	}
55	
56	/**
57	 * Python `UnicodeEncodeError` as raised by `str.encode('UTF-8')` when the
58	 * string holds a lone surrogate produced by argv's surrogateescape decoding.
59	 */
60	export class PyUnicodeEncodeError extends PyError {
61	  /**
62	   * @param {number} codePoint The offending code point (a lone surrogate).
63	   * @param {number} position Index of that code point, counted in Python code
64	   *   points (astral characters count as one).
65	   */
66	  constructor(codePoint, position) {
67	    super(
68	      'UnicodeEncodeError',
69	      `'utf-8' codec can't encode character '${escapeCodePoint(codePoint)}' ` +
70	        `in position ${position}: surrogates not allowed`,
71	    );
72	    this.codePoint = codePoint;
73	    this.position = position;
74	  }
75	}
76	
77	/**
78	 * Render one code point the way Python escapes it inside `repr()` and inside
79	 * codec error messages: `\xNN`, `\uNNNN` or `\UNNNNNNNN`, always lowercase hex.
80	 * @param {number} cp
81	 * @returns {string}
82	 */
83	export function escapeCodePoint(cp) {
84	  if (cp < 0x100) return '\\x' + cp.toString(16).padStart(2, '0');
85	  if (cp < 0x10000) return '\\u' + cp.toString(16).padStart(4, '0');
86	  return '\\U' + cp.toString(16).padStart(8, '0');
87	}
88	
89	/**
90	 * Byte offsets differ from Python's character offsets, so locate `needle` and
91	 * report where it starts measured in code points rather than UTF-16 units.
92	 * @param {string} haystack
93	 * @param {string} needle
94	 * @returns {number} Code-point index, or -1 when absent.
95	 */
96	function codePointIndexOf(haystack, needle) {
97	  const at = haystack.indexOf(needle);
98	  if (at < 0) return -1;
99	  return Array.from(haystack.slice(0, at)).length;
100	}
101	
102	/**
103	 * Work out which columns of a frame's source line get underlined with `^`.
104	 * `caret` may be an explicit `{start, length}` span or `true`, in which case
105	 * the frame's `caretExpr` sub-expression is located inside the source (falling
106	 * back to underlining the whole line).
107	 * @param {{source?: string, caret?: boolean|{start: number, length: number}, caretExpr?: string}} frame
108	 * @returns {{start: number, length: number}|null}
109	 */
110	function caretSpan(frame) {
111	  const { caret, source } = frame;
112	  if (!caret || typeof source !== 'string') return null;
113	  if (typeof caret === 'object') {
114	    return { start: caret.start, length: caret.length };
115	  }
116	  if (typeof frame.caretExpr === 'string') {
117	    const start = codePointIndexOf(source, frame.caretExpr);
118	    if (start >= 0) return { start, length: Array.from(frame.caretExpr).length };
119	  }
120	  return { start: 0, length: Array.from(source).length };
121	}
122	
123	/**
124	 * The final `Type: message` line. Python omits the colon when `str(exc)` is
125	 * empty.
126	 * @param {unknown} err
127	 * @returns {string}
128	 */
129	function exceptionLine(err) {
130	  const type = (err && (err.pyType || err.name)) || 'Exception';
131	  const message = err && err.pyMessage !== undefined ? err.pyMessage : err && err.message;
132	  return message ? `${type}: ${message}` : `${type}`;
133	}
134	
135	/**
136	 * Format a CPython traceback from innermost-last frames.
137	 * @param {Array<{file: string, line: number, name: string, source?: string,
138	 *   caret?: boolean|{start: number, length: number}, caretExpr?: string}>} frames
139	 * @param {unknown} err
140	 * @returns {string} Newline-terminated traceback text.
141	 */
142	export function formatTraceback(frames, err) {
143	  const lines = ['Traceback (most recent call last):'];
144	  for (const frame of frames) {
145	    lines.push(`  File "${frame.file}", line ${frame.line}, in ${frame.name}`);
146	    // Frames from the bundled pbkdf2.py have no source available, so
147	    // PyInstaller prints only the location line for them.
148	    if (typeof frame.source !== 'string' || frame.source.length === 0) continue;
149	    lines.push(' '.repeat(SOURCE_INDENT) + frame.source);
150	    const span = caretSpan(frame);
151	    if (span && span.length > 0) {
152	      lines.push(' '.repeat(SOURCE_INDENT + span.start) + '^'.repeat(span.length));
153	    }
154	  }
155	  lines.push(exceptionLine(err));
156	  return lines.join('\n') + '\n';
157	}
158	
159	/**
160	 * Produce the complete stderr text for a fatal error: the traceback plus
161	 * PyInstaller's trailing failure line.
162	 * @param {unknown} err
163	 * @returns {string} Newline-terminated stderr text.
164	 */
165	export function renderFatal(err) {
166	  const setupLine =
167	    err && Number.isInteger(err.frameLine) ? err.frameLine : DEFAULT_SETUP_LINE;
168	  const frames = [
169	    {
170	      file: 'test2.py',
171	      line: 12,
172	      name: '<module>',
173	      source: MAIN_SOURCE,
174	      caret: true,
175	      caretExpr: MAIN_CARET_EXPR,
176	    },
177	    { file: 'pbkdf2.py', line: 141, name: '__init__' },
178	    { file: 'pbkdf2.py', line: setupLine, name: '_setup' },
179	  ];
180	  return (
181	    formatTraceback(frames, err) +
182	    `[PYI-${process.pid}:ERROR] Failed to execute script 'test2' due to unhandled exception!\n`
183	  );
184	}
185

