const MAIN_SOURCE =
  'result = pbkdf2.PBKDF2(args.a, args.b, iterations=args.c).read(20)  # 派生 20 字节密钥';
const MAIN_CARET_EXPR = 'pbkdf2.PBKDF2(args.a, args.b, iterations=args.c)';

/** `pbkdf2.py` line reported for `_setup` when the error carries no `frameLine`. */
const DEFAULT_SETUP_LINE = 205;

/** Base class for every exception we mirror from Python. */
export class PyError extends Error {
  /**
   * @param {string} type Python exception class name, e.g. `'ValueError'`.
   * @param {string} message Python's `str(exc)` text.
   */
  constructor(type, message) {
    super(message);
    this.name = type;
    this.pyType = type;
    this.pyMessage = message;
    /**
     * Line inside `pbkdf2.py`'s `_setup` that raised. The raising module tags
     * this (193 passphrase, 197 salt, 205 iterations) so the traceback's last
     * frame matches the real interpreter.
     * @type {number|undefined}
     */
    this.frameLine = undefined;
  }
}

/** Python `ValueError`. */
export class PyValueError extends PyError {
  /** @param {string} message */
  constructor(message) {
    super('ValueError', message);
  }
}

/**
 * Python `UnicodeEncodeError` as raised by `str.encode('UTF-8')` when the
 * string holds a lone surrogate produced by argv's surrogateescape decoding.
 */
export class PyUnicodeEncodeError extends PyError {
  /**
   * @param {number} codePoint The offending code point (a lone surrogate).
   * @param {number} position Index of that code point, counted in Python code
   *   points (astral characters count as one).
   */
  constructor(codePoint, position) {
    super(
      'UnicodeEncodeError',
      `'utf-8' codec can't encode character '${escapeCodePoint(codePoint)}' ` +
        `in position ${position}: surrogates not allowed`,
    );
    this.codePoint = codePoint;
    this.position = position;
  }
}

/**
 * Render one code point the way Python escapes it inside `repr()` and inside
 * codec error messages: `\xNN`, `\uNNNN` or `\UNNNNNNNN`, always lowercase hex.
 * @param {number} cp
 * @returns {string}
 */
export function escapeCodePoint(cp) {
  if (cp < 0x100) return '\\x' + cp.toString(16).padStart(2, '0');
  if (cp < 0x10000) return '\\u' + cp.toString(16).padStart(4, '0');
  return '\\U' + cp.toString(16).padStart(8, '0');
}

/**
 * Byte offsets differ from Python's character offsets, so locate `needle` and
 * report where it starts measured in code points rather than UTF-16 units.
 * @param {string} haystack
 * @param {string} needle
 * @returns {number} Code-point index, or -1 when absent.
 */
function codePointIndexOf(haystack, needle) {
  const at = haystack.indexOf(needle);
  if (at < 0) return -1;
  return Array.from(haystack.slice(0, at)).length;
}

/**
 * Work out which columns of a frame's source line get underlined with `^`.
 * `caret` may be an explicit `{start, length}` span or `true`, in which case
 * the frame's `caretExpr` sub-expression is located inside the source (falling
 * back to underlining the whole line).
 * @param {{source?: string, caret?: boolean|{start: number, length: number}, caretExpr?: string}} frame
 * @returns {{start: number, length: number}|null}
 */
function caretSpan(frame) {
  const { caret, source } = frame;
  if (!caret || typeof source !== 'string') return null;
  if (typeof caret === 'object') {
    return { start: caret.start, length: caret.length };
  }
  if (typeof frame.caretExpr === 'string') {
    const start = codePointIndexOf(source, frame.caretExpr);
    if (start >= 0) return { start, length: Array.from(frame.caretExpr).length };
  }
  return { start: 0, length: Array.from(source).length };
}

/**
 * The final `Type: message` line. Python omits the colon when `str(exc)` is
 * empty.
 * @param {unknown} err
 * @returns {string}
 */
function exceptionLine(err) {
  const type = (err && (err.pyType || err.name)) || 'Exception';
  const message = err && err.pyMessage !== undefined ? err.pyMessage : err && err.message;
  return message ? `${type}: ${message}` : `${type}`;
}

/**
 * Format a CPython traceback from innermost-last frames.
 * @param {Array<{file: string, line: number, name: string, source?: string,
 *   caret?: boolean|{start: number, length: number}, caretExpr?: string}>} frames
 * @param {unknown} err
 * @returns {string} Newline-terminated traceback text.
 */
export function formatTraceback(frames, err) {
  const lines = ['Traceback (most recent call last):'];
  for (const frame of frames) {
    lines.push(`  File "${frame.file}", line ${frame.line}, in ${frame.name}`);
    // Frames from the bundled pbkdf2.py have no source available, so
    // PyInstaller prints only the location line for them.
    if (typeof frame.source !== 'string' || frame.source.length === 0) continue;
    lines.push(' '.repeat(SOURCE_INDENT) + frame.source);
    const span = caretSpan(frame);
    if (span && span.length > 0) {
      lines.push(' '.repeat(SOURCE_INDENT + span.start) + '^'.repeat(span.length));
    }
  }
  lines.push(exceptionLine(err));
  return lines.join('\n') + '\n';
}

/**
 * Produce the complete stderr text for a fatal error: the traceback plus
 * PyInstaller's trailing failure line.
 * @param {unknown} err
 * @returns {string} Newline-terminated stderr text.
 */
export function renderFatal(err) {
  const setupLine =
    err && Number.isInteger(err.frameLine) ? err.frameLine : DEFAULT_SETUP_LINE;
  const frames = [
    {
      file: 'test2.py',
      line: 12,
      name: '<module>',
      source: MAIN_SOURCE,
      caret: true,
      caretExpr: MAIN_CARET_EXPR,
    },
    { file: 'pbkdf2.py', line: 141, name: '__init__' },
    { file: 'pbkdf2.py', line: setupLine, name: '_setup' },
  ];
  return (
    formatTraceback(frames, err) +
    `[PYI-${process.pid}:ERROR] Failed to execute script 'test2' due to unhandled exception!\n`
  );
}

