/**
 * Python `int(str)` and `repr(str)` semantics, reproduced closely enough that
 * argparse's `type=int` accepts and rejects exactly what CPython does.
 */

import { PyValueError, escapeCodePoint } from './pyerror.mjs';

// Re-exported so callers can reach Python's ValueError through this module too.
export { PyValueError };

/** Widest contiguous run of Nd code points in Unicode is 50; scan generously. */
const RUN_SCAN_LIMIT = 100;

const ND_RE = /\p{Nd}/u;
// Python's str.isprintable(): false for these categories, with U+0020 as the
// one explicit exception (it is Zs but still prints as itself).
const NON_PRINTABLE_RE = /[\p{Cc}\p{Cf}\p{Cs}\p{Co}\p{Cn}\p{Zl}\p{Zp}\p{Zs}]/u;

// Node 18 bundles ICU 74 (Unicode 15.1); the reference interpreter carries
// Unicode 15.0. The only assignment difference between those releases is CJK
// Unified Ideographs Extension I, which 15.1 added and 15.0 leaves unassigned
// (Cn, hence non-printable). Verified against the reference: this whole range
// escapes as \U0002xxxx, while Extension H right after it prints literally.
const CJK_EXT_I_LO = 0x2ebf0;
const CJK_EXT_I_HI = 0x2ee5d;

/** Raised when a string is not a valid Python base-10 integer literal. */
export class PyIntParseError extends Error {
  /** @param {string} text The rejected input. */
  constructor(text) {
    super(`invalid literal for int() with base 10: ${pyRepr(text)}`);
    this.name = 'PyIntParseError';
    this.text = text;
  }
}

/**
 * ASCII whitespace as recognised by CPython's `Py_ISSPACE`, which is what the
 * integer parser itself uses. Note this deliberately excludes U+001C-U+001F:
 * `str.strip()` treats those as whitespace but `int()` does not.
 * @param {string} ch
 */
function isAsciiSpace(ch) {
  return ch === ' ' || (ch >= '\t' && ch <= '\r');
}

/**
 * Non-ASCII whitespace as recognised by CPython's `Py_UNICODE_ISSPACE`.
 * @param {number} cp
 */
function isUnicodeSpace(cp) {
  return (
    cp === 0x85 ||
    cp === 0xa0 ||
    cp === 0x1680 ||
    (cp >= 0x2000 && cp <= 0x200a) ||
    cp === 0x2028 ||
    cp === 0x2029 ||
    cp === 0x202f ||
    cp === 0x205f ||
    cp === 0x3000
  );
}

/** @param {number} cp */
function isNd(cp) {
  return cp >= 0 && cp <= 0x10ffff && ND_RE.test(String.fromCodePoint(cp));
}

/**
 * Numeric value of a Unicode decimal digit, i.e. CPython's
 * `Py_UNICODE_TODECIMAL`.
 *
 * Nd code points always come in complete, contiguous 0-9 blocks, but several
 * blocks can sit back to back (the mathematical digits occupy one unbroken
 * 50-code-point run at U+1D7CE-U+1D7FF). Simply walking back to the first
 * non-Nd neighbour would therefore mis-value every block but the first, so
 * find the whole run and take the offset modulo 10.
 *
 * @param {number} cp
 * @returns {number} 0-9, or -1 when `cp` is not a decimal digit.
 */
function decimalValue(cp) {
  if (!isNd(cp)) return -1;
  let lo = cp;
  while (lo > 0 && cp - lo < RUN_SCAN_LIMIT && isNd(lo - 1)) lo--;
  let hi = cp;
  while (hi < 0x10ffff && hi - cp < RUN_SCAN_LIMIT && isNd(hi + 1)) hi++;
  const runLength = hi - lo + 1;
  // A run that is not a whole number of blocks cannot happen in Unicode;
  // fall back to treating the run start as zero if one ever appears.
  if (runLength % 10 !== 0) return Math.min(cp - lo, 9);
  return (cp - lo) % 10;
}

/**
 * CPython's `_PyUnicode_TransformDecimalAndSpaceToASCII`: code points below 127
 * pass through untouched, Unicode whitespace collapses to a plain space, and
 * Unicode decimal digits become their ASCII equivalents. Anything else becomes
 * `'?'`, which the ASCII parser then rejects.
 * @param {string} text
 * @returns {string}
 */
function transformDecimalAndSpace(text) {
  let out = '';
  for (const ch of text) {
    const cp = ch.codePointAt(0);
    if (cp < 127) {
      out += ch;
    } else if (isUnicodeSpace(cp)) {
      out += ' ';
    } else {
      const digit = decimalValue(cp);
      out += digit >= 0 ? String(digit) : '?';
    }
  }
  return out;
}

/**
 * CPython's `PyLong_FromString` for base 10, over an already-ASCII string.
 * @param {string} text
 * @returns {number|null} The value, or null when the literal is malformed.
 */
function parseAsciiInt(text) {
  const end = text.length;
  let i = 0;
  while (i < end && isAsciiSpace(text[i])) i++;

  let negative = false;
  if (i < end && (text[i] === '+' || text[i] === '-')) {
    negative = text[i] === '-';
    i++;
  }

  // An underscore is only legal strictly between two digits, so track whether
  // a digit is currently mandatory. It starts mandatory (rejecting `_10` and
  // `+_1`) and becomes mandatory again after every underscore (rejecting `1__0`
  // and, once the loop ends, `10_`).
  let digits = '';
  let digitRequired = true;
  while (i < end) {
    const ch = text[i];
    if (ch >= '0' && ch <= '9') {
      digits += ch;
      digitRequired = false;
      i++;
    } else if (ch === '_' && !digitRequired) {
      digitRequired = true;
      i++;
    } else {
      break;
    }
  }
  if (digits.length === 0 || digitRequired) return null;

  while (i < end && isAsciiSpace(text[i])) i++;
  if (i !== end) return null;

  // Python integers are arbitrary precision; accumulate exactly and only then
  // narrow to a Number (which may saturate to Infinity for absurd inputs).
  const magnitude = BigInt(digits);
  return Number(negative ? -magnitude : magnitude);
}

/**
 * Python's `int(str)`.
 * @param {string} text
 * @returns {number}
 * @throws {PyIntParseError} When `text` is not a valid base-10 integer.
 */
export function pyInt(text) {
  const value = parseAsciiInt(transformDecimalAndSpace(text));
  if (value === null) throw new PyIntParseError(text);
  return value;
}

/** @param {number} cp */
function isPrintable(cp) {
  if (cp === 0x20) return true;
  if (cp >= CJK_EXT_I_LO && cp <= CJK_EXT_I_HI) return false;
  return !NON_PRINTABLE_RE.test(String.fromCodePoint(cp));
}

/**
 * Python's `repr()` of a str, as embedded in argparse's
 * `invalid int value: 'x'` message.
 *
 * Single quotes are preferred; double quotes are used only when the string
 * contains a single quote but no double quote. Backslash, newline, carriage
 * return and tab get named escapes, everything non-printable gets a numeric
 * escape (including lone surrogates, which render as `\udcXX`).
 *
 * @param {string} text
 * @returns {string}
 */
export function pyRepr(text) {
  const quote = text.includes("'") && !text.includes('"') ? '"' : "'";
  let out = quote;
  for (const ch of text) {
    if (ch === quote || ch === '\\') {
      out += '\\' + ch;
      continue;
    }
    if (ch === '\n') {
      out += '\\n';
      continue;
    }
    if (ch === '\r') {
      out += '\\r';
      continue;
    }
    if (ch === '\t') {
      out += '\\t';
      continue;
    }
    const cp = ch.codePointAt(0);
    out += isPrintable(cp) ? ch : escapeCodePoint(cp);
  }
  return out + quote;
}

