/**
 * A minimal clone of CPython's `argparse`, covering exactly the surface the
 * reference program uses: three required long options with store actions, an
 * automatic `-h/--help`, and the same error text, exit codes and stream
 * routing.
 *
 * The quirks reproduced here were all confirmed against the reference binary;
 * each one is called out at the code that implements it.
 */

import { writeSync } from 'node:fs';
import process from 'node:process';

import { pyRepr } from './pyint.mjs';

/** Character that introduces an optional argument. */
const PREFIX = '-';

/**
 * argparse only refuses to treat a `-`-leading token as a value when it cannot
 * possibly be a negative number. CPython's test is this regex; because our
 * parser declares no option that looks like a negative number, anything
 * matching it is a value. Verified: `--a -1` and `--a -1.5` succeed while
 * `--a -x` fails with "expected one argument".
 */
const NEGATIVE_NUMBER_RE = /^-\d+$|^-\d*\.\d+$/;

/**
 * Thrown instead of calling `process.exit`, so the entry point can flush and
 * set an exit status without the parser reaching into the process.
 */
export class SystemExit extends Error {
  /** @param {number} code */
  constructor(code) {
    super(`SystemExit: ${code}`);
    this.name = 'SystemExit';
    this.code = code;
  }
}

/**
 * Write to a file descriptor synchronously, so nothing is lost when the process
 * exits immediately afterwards.
 * @param {number} fd 1 for stdout, 2 for stderr.
 * @param {string} text
 */
function writeAll(fd, text) {
  if (text.length === 0) return;
  const buf = Buffer.from(text, 'utf8');
  let off = 0;
  while (off < buf.length) off += writeSync(fd, buf, off, buf.length - off);
}

/** One declared option. */
class Action {
  /**
   * @param {string} flag Long flag including the `--` prefix.
   * @param {{type?: (value: string) => unknown, required?: boolean,
   *   dest?: string, help?: string, metavar?: string}} options
   */
  constructor(flag, options = {}) {
    this.flag = flag;
    this.dest = options.dest ?? flag.replace(/^-+/, '').replace(/-/g, '_');
    this.type = options.type ?? String;
    this.required = options.required ?? false;
    this.help = options.help ?? '';
    // argparse's default metavar for a store action is the dest upper-cased.
    this.metavar = options.metavar ?? this.dest.toUpperCase();
    this.takesValue = true;
  }

  /** How the option is rendered inside the usage line, e.g. `--a A`. */
  get usageFragment() {
    return `${this.flag} ${this.metavar}`;
  }

  /** How the option is rendered in the left column of the options list. */
  get invocation() {
    return `${this.flag} ${this.metavar}`;
  }
}

/** The automatic `-h, --help` action. */
class HelpAction extends Action {
  constructor() {
    super('--help', { dest: 'help', help: 'show this help message and exit' });
    this.takesValue = false;
    this.flags = ['-h', '--help'];
  }

  get usageFragment() {
    return '-h';
  }

  get invocation() {
    return '-h, --help';
  }
}

/** Raised internally to unwind to `error()` with an argparse message. */
class ArgumentError extends Error {
  /** @param {string} message */
  constructor(message) {
    super(message);
    this.name = 'ArgumentError';
  }
}

export class ArgumentParser {
  /** @param {{prog?: string}} [options] */
  constructor(options = {}) {
    this.prog = options.prog ?? 'prog';
    /** @type {Action[]} Declaration order drives usage and error ordering. */
    this.actions = [new HelpAction()];
  }

  /**
   * Declare an option. Only long flags with a single value are supported,
   * which is all the reference program declares.
   * @param {string} flag
   * @param {{type?: (value: string) => unknown, required?: boolean,
   *   dest?: string, help?: string, metavar?: string}} [options]
   * @returns {Action}
   */
  add_argument(flag, options = {}) {
    const action = new Action(flag, options);
    this.actions.push(action);
    return action;
  }

  /** @returns {string} The `usage: ...` line, newline-terminated. */
  format_usage() {
    const parts = this.actions.map((a) => `[${a.usageFragment}]`);
    // Required options lose the brackets that mark optionality.
    const rendered = this.actions.map((a, i) =>
      a.required ? a.usageFragment : parts[i],
    );
    return `usage: ${this.prog} ${rendered.join(' ')}\n`;
  }

  /** @returns {string} The full `--help` text, newline-terminated. */
  format_help() {
    const rows = this.actions.map((a) => [a.invocation, a.help]);
    // argparse lays the help column out at a tab stop two spaces past the
    // widest invocation, but never further right than column 24.
    const indent = 2;
    const maxInvocation = Math.max(...rows.map((r) => r[0].length));
    const helpColumn = Math.min(indent + maxInvocation + 2, 24);
    const lines = [this.format_usage(), '\noptions:\n'];
    for (const [invocation, help] of rows) {
      if (!help) {
        lines.push(`${' '.repeat(indent)}${invocation}\n`);
        continue;
      }
      const left = ' '.repeat(indent) + invocation;
      const pad = ' '.repeat(Math.max(helpColumn - left.length, 2));
      lines.push(`${left}${pad}${help}\n`);
    }
    return lines.join('');
  }

  /**
   * Print `message` to stderr behind the usage line and exit with status 2.
   * @param {string} message
   * @returns {never}
   */
  error(message) {
    writeAll(2, this.format_usage());
    writeAll(2, `${this.prog}: error: ${message}\n`);
    throw new SystemExit(2);
  }

  /**
   * @param {number} code
   * @param {string} [message] Written to stdout when the exit is successful.
   * @returns {never}
   */
  exit(code = 0, message) {
    if (message) writeAll(code === 0 ? 1 : 2, message);
    throw new SystemExit(code);
  }

  /**
   * Decide whether `token` introduces an option or is a plain value.
   *
   * Mirrors argparse's `_parse_optional`. All four escape hatches are load
   * bearing and were verified against the reference: `--a ''`, `--a -1`,
   * `--a ' -x'` and `--a '-x y'` all pass their token through as a value.
   * @param {string} token
   * @returns {Action|null|undefined} The matching action, `null` when the token
   *   looks like an option but matches nothing, `undefined` when it is a value.
   */
  #classify(token) {
    if (token.length === 0) return undefined;
    if (!token.startsWith(PREFIX)) return undefined;

    const eq = token.indexOf('=');
    const head = eq >= 0 ? token.slice(0, eq) : token;
    for (const action of this.actions) {
      const flags = action.flags ?? [action.flag];
      if (flags.includes(head)) return action;
    }

    // A bare `-` and anything numeric-looking is a value, not an option.
    if (NEGATIVE_NUMBER_RE.test(token)) return undefined;
    if (token.includes(' ')) return undefined;
    return null;
  }

  /**
   * Parse `argv`, collecting anything unrecognised.
   * @param {string[]} argv
   * @returns {[Record<string, unknown>, string[]]}
   */
  parse_known_args(argv) {
    /** @type {Record<string, unknown>} */
    const namespace = Object.create(null);
    /** @type {string[]} */
    const extras = [];
    const seen = new Set();

    for (let i = 0; i < argv.length; i++) {
      const token = argv[i];
      const action = this.#classify(token);

      if (action === undefined) {
        extras.push(token);
        continue;
      }
      if (action === null) {
        extras.push(token);
        continue;
      }
      if (action instanceof HelpAction) {
        writeAll(1, this.format_help());
        throw new SystemExit(0);
      }

      const eq = token.indexOf('=');
      let raw;
      if (eq >= 0) {
        // The explicit `--a=value` form takes its value verbatim, so it can
        // carry a leading dash that the separated form would reject.
        raw = token.slice(eq + 1);
      } else {
        const next = i + 1 < argv.length ? argv[i + 1] : undefined;
        if (next === undefined || this.#classify(next) !== undefined) {
          throw new ArgumentError(`argument ${action.flag}: expected one argument`);
        }
        raw = next;
        i++;
      }

      let value;
      try {
        value = action.type(raw);
      } catch {
        const typeName = action.type === String ? 'str' : action.type.typeName || 'int';
        throw new ArgumentError(
          `argument ${action.flag}: invalid ${typeName} value: ${pyRepr(raw)}`,
        );
      }
      // A repeated option simply overwrites: last one wins.
      namespace[action.dest] = value;
      seen.add(action);
    }

    // argparse checks required options at the end of parse_known_args, which is
    // why a missing required option outranks an unrecognised one. Verified:
    // `-a x -b y -c 100` reports all three as required rather than as extras.
    const missing = this.actions.filter((a) => a.required && !seen.has(a));
    if (missing.length > 0) {
      throw new ArgumentError(
        `the following arguments are required: ${missing.map((a) => a.flag).join(', ')}`,
      );
    }
    return [namespace, extras];
  }

  /**
   * Parse `argv` and reject leftovers.
   * @param {string[]} argv
   * @returns {Record<string, unknown>}
   */
  parse_args(argv) {
    let namespace;
    let extras;
    try {
      [namespace, extras] = this.parse_known_args(argv);
    } catch (err) {
      if (err instanceof ArgumentError) this.error(err.message);
      throw err;
    }
    if (extras.length > 0) {
      this.error(`unrecognized arguments: ${extras.join(' ')}`);
    }
    return namespace;
  }
}

export default ArgumentParser;

